@pragma('vm:entry-point')
void fn0() {
  int n = 4;
  int total = (1 << n) - 1;
  int minBit = total;
  for (int i = 0; i < n; i++) {
    int bit = 1 << i;
    if ((total & bit) != 0) {
      if (bit < minBit) minBit = bit;
    }
  }
  print(minBit);
}

